def parse(s):
    if s == "":
        raise ValueError("empty")
    return int(s)

def run_all(items):
    results, errors = [], []
    for item in items:
        try:
            results.append(parse(item))
        except Exception as exc:
            errors.append(exc)
    if errors:
        raise ExceptionGroup("batch failed", errors)
    return results

def summarize(items):
    n_value = n_type = 0
    try:
        run_all(items)
    except* ValueError as group:
        n_value = len(group.exceptions)
    except* TypeError as group:
        n_type = len(group.exceptions)
    return n_value, n_type

print(summarize(["1", "", "x", None, "5"]))
